/** Lifecycle code emitted around retained controllers; keep ownership/cleanup contracts explicit. */
function runtimePrefix(imports) {
  const header = [
    "// Generated by scripts/prepare-workspace.cjs. Edit source modules instead.",
    ...imports.map((pair) => {
      const [name, file] = pair.split(":");
      return "import " + name + " from '../lib/domain/" + file + ".cjs';";
    }),
    "import { workspaceShell } from '../components/workspace-shell.mjs';",
  ].join("\n");
  return (
    header +
    "\n" +
    `
export function mountWorkspace(root, { onNavigate = () => {} } = {}) {
  root.innerHTML = workspaceShell;
  // Scope all selectors to this island; React owns only the surrounding container.
  const document = {
    querySelector: selector => root.querySelector(selector),
    querySelectorAll: selector => root.querySelectorAll(selector),
    createElement: (...args) => root.ownerDocument.createElement(...args),
  };
  const timers = new Set();
  const setTimeout = (callback, delay) => {
    const id = globalThis.setTimeout(() => { timers.delete(id); callback(); }, delay);
    timers.add(id);
    return id;
  };
  const pending = new Set();
  const fetch = async (url, options = {}) => {
    const controller = new AbortController();
    pending.add(controller);
    const signal = options.signal
      ? AbortSignal.any([controller.signal, options.signal])
      : controller.signal;
    try { return await globalThis.fetch(url, { ...options, signal }); }
    finally { pending.delete(controller); }
  };
`
  );
}
const runtimeSuffix = `
// UI-originated navigation updates the URL; show() handles router-originated changes.
const navigateWorkspace = navigate;
navigate = function(nextPage) {
  navigateWorkspace(nextPage);
  onNavigate(nextPage);
};
return {
  show(nextPage) { if (page !== nextPage) navigateWorkspace(nextPage); },
  get currentPage() { return page; },
  destroy() {
    page = 'disposed';
    timers.forEach(id => globalThis.clearTimeout(id));
    pending.forEach(controller => controller.abort());
    timers.clear();
    pending.clear();
  },
};
}
`;
module.exports = { runtimePrefix, runtimeSuffix };
